          reason: `no indexed file at ${pathPart}`,
        });

return candidates.map((sym) => {
    const siblings = sym.file ? (perFile.get(sym.file) ?? 1) : 1;
    const conf = siblings >= 2 ? 0.8 : 0.6;
    return { symbol: sym, method: 'identifier' as Method, conf };
